INSERT INTO tips (id, title, text, read_more_url) VALUES
    (1, 'Nature Restores Focus', 'Spending time in natural environments helps restore directed attention after mental fatigue. \n\nEven a short walk among trees can improve concentration and cognitive performance.', 'https://doi.org/10.1177/0013916518774400'),
    (2, 'Brain Loves Clear Triggers', 'Habits become easier when they are linked to specific cues. \n\nA clear trigger such as a time, place, or event helps your brain know exactly when to act.', 'https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions'),
    (3, 'If-Then Planning Works', 'People are more likely to follow through on goals when they create concrete plans. \n\nDefining what you''ll do in a specific situation reduces hesitation and decision-making.', 'https://doi.org/10.1016/j.jcps.2009.08.004'),
    (4, 'Focus Is a Limited Resource', 'Concentration requires mental effort and can become depleted over time. \n\nRecovery periods help maintain performance and prevent cognitive exhaustion.', 'https://doi.org/10.1177/0013916518774400'),
    (5, 'Flow Happens Between Boredom and Anxiety', 'Flow is most likely when a challenge matches your skill level. \n\nTasks that are too easy create boredom, while tasks that are too difficult create stress.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (6, 'Notifications Have a Hidden Cost', 'Interruptions do more than break focus in the moment. \n\nYour brain often continues thinking about the distraction, reducing performance long after it is gone.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (7, 'Specific Beats Motivated', 'Motivation can fluctuate from day to day. \n\nClear plans about when and where you''ll act are often more reliable than waiting to feel motivated.', 'https://doi.org/10.1177/0146167204271308'),
    (8, 'Flow Changes Time Perception', 'During deep concentration, people often lose track of time. \n\nHours can feel like minutes when attention is fully absorbed by a meaningful task.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (9, 'Small Starts Beat Big Promises', 'Starting with a tiny action lowers resistance and makes consistency easier. \n\nSmall beginnings often grow into larger habits over time.', 'https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions'),
    (10, 'Environment Shapes Behavior', 'Your surroundings influence your actions more than most people realize. \n\nDesigning your environment can make good habits easier and bad habits harder.', 'https://doi.org/10.1016/j.jcps.2009.08.004'),
    (11, 'Attention Is Trainable', 'Concentration is a skill that improves with practice. \n\nActivities that require sustained focus can strengthen your ability to resist distractions.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (12, 'Reflection Needs Mental Space', 'Constant stimulation leaves little room for reflection. \n\nQuiet moments allow the brain to process experiences and form deeper insights.', 'https://doi.org/10.1177/0013916518774400'),
    (13, 'Goals Need Feedback', 'Clear goals and immediate feedback are key ingredients of flow. \n\nKnowing how you''re doing helps maintain engagement and motivation.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (14, 'Habits Reduce Decision Fatigue', 'Every decision consumes mental energy. \n\nTurning useful behaviors into habits frees cognitive resources for more important choices.', 'https://doi.org/10.1016/j.jcps.2009.08.004'),
    (15, 'Focus Loves Single-Tasking', 'Concentrating on one task at a time is often more efficient than switching between several. \n\nTask switching carries hidden mental costs.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (16, 'Your Brain Scans for Cues', 'Once you define a habit trigger, your attention becomes more sensitive to it.  Brain naturally starts noticing opportunities to act.', 'https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions'),
    (17, 'Deep Work Feels Effortless', 'High-focus states often feel surprisingly smooth despite requiring significant skill. \n\nEffort becomes less noticeable when attention is fully engaged.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (18, 'Motivation Often Follows Action', 'Many people wait for motivation before starting. In reality, taking action is often what creates the motivation to continue.', 'https://doi.org/10.1037/0003-066X.54.7.493'),
    (19, 'Walking Can Improve Thinking', 'Walking increases blood flow and can support creative thinking. \n\nMany people find that ideas come more easily while moving.', 'https://doi.org/10.1177/0013916518774400'),
    (20, 'Boredom Can Be Useful', 'Moments without stimulation encourage reflection and imagination. \n\nSome of our best ideas emerge when there is nothing demanding our attention.', 'https://doi.org/10.1177/0013916518774400'),
    (21, 'Habits Thrive on Consistency', 'Habits grow stronger when repeated in the same context. \n\nConsistency teaches your brain to associate a situation with a specific behavior until it becomes automatic.', 'https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions'),
    (22, 'Focus Is Easier With Purpose', 'Meaningful goals naturally attract attention. \n\nWhen you understand why a task matters, it becomes easier to stay engaged and resist distractions.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (23, 'Soft Fascination Restores Attention', 'Gentle stimuli such as clouds, flowing water, or rustling leaves engage the mind without demanding effort. \n\nThis allows attention to recover from fatigue.', 'https://doi.org/10.1177/0013916518774400'),
    (24, 'Multitasking Is Mostly Switching', 'What we call multitasking is often rapid task-switching. \n\nEach switch carries a small cognitive cost that can reduce efficiency and increase mistakes.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (25, 'Strong Habits Need Strong Cues', 'The clearer and more visible a cue is, the more likely a habit is to occur. \n\nEffective triggers remove uncertainty about when to act.', 'https://doi.org/10.1177/0146167204271308'),
    (26, 'Flow Rewards Itself', 'Flow activities are often enjoyable regardless of external rewards. People engage in them because the experience itself feels satisfying and meaningful.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (27, 'Mental Recovery Improves Performance', 'Productive people do not focus endlessly. Strategic recovery periods help maintain concentration, creativity, and decision-making quality.', 'https://doi.org/10.1177/0013916518774400'),
    (28, 'Tiny Wins Build Momentum', 'Small accomplishments create a sense of progress. \n\nThat feeling often increases motivation and makes future actions easier to complete.', 'https://doi.org/10.1016/j.jcps.2009.08.004'),
    (29, 'Attention Follows Interest', 'The brain naturally allocates more resources to things it finds meaningful, novel or rewarding. \n\nInterest is one of the strongest drivers of focus.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (30, 'Clarity Beats Complexity', 'Simple plans are easier to remember and execute. \n\nThe more complicated a system becomes, the more opportunities there are to abandon it.', 'https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions'),
    (31, 'The Zeigarnik Effect', 'Unfinished tasks tend to remain active in the mind. This is why unresolved goals often keep returning to your thoughts until they are completed.', 'https://en.wikipedia.org/wiki/Zeigarnik_effect'),
    (32, 'Starting Is the Hardest Part', 'Beginning a task often requires more effort than continuing it. \n\nOnce momentum is established, the brain becomes less resistant to the activity.', 'https://behavioralscientist.org/how-to-build-habits-by-starting-small/'),
    (33, 'Self-Control Is Contextual', 'People with strong self-control often avoid temptation rather than constantly resisting it. \n\nSmart environments reduce the need for willpower.', 'https://doi.org/10.1177/0146167210390247'),
    (34, 'Your Future Self Feels Like a Stranger', 'We naturally value immediate rewards more than future benefits. \n\nBuilding a stronger connection with your future self can improve long-term decision-making.', 'https://www.apa.org/monitor/2013/03/mind-time'),
    (35, 'Attention Is Selective', 'The brain filters enormous amounts of information every second. What you notice depends heavily on your goals, expectations, and current focus.', 'https://www.simonsfoundation.org/2015/05/14/the-invisible-gorilla-experiment/'),
    (36, 'Progress Fuels Motivation', 'Visible progress is one of the strongest motivators available. Even small signs of advancement can increase persistence and confidence.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (37, 'Repetition Builds Identity', 'The actions you repeat influence how you see yourself. \n\nOver time, habits become evidence that supports your self-image.', 'https://jamesclear.com/identity-based-habits'),
    (38, 'Sleep Protects Focus', 'Attention, memory, and decision-making all depend on quality sleep. \n\nEven mild sleep deprivation can significantly reduce cognitive performance.', 'https://www.sleepfoundation.org/sleep-deprivation'),
    (39, 'The Brain Predicts Rewards', 'Anticipating a reward activates motivational systems in the brain. \n\nOften, the expectation of a reward is more powerful than the reward itself.', 'https://www.nature.com/articles/nn.2665'),
    (40, 'Habits Love Consistency', 'Repeating an action at the same time or place strengthens habit formation. \n\nPredictable routines reduce the need for conscious effort.', 'https://doi.org/10.1002/ejsp.674'),
    (41, 'Attention Is Easily Captured', 'Sudden sounds, movement, novelty, and contrast naturally attract attention. \n\nThis tendency helped our ancestors survive but can create distractions today.', 'https://www.ncbi.nlm.nih.gov/books/NBK11509/'),
    (42, 'Success Breeds Success', 'Small victories increase confidence and make future challenges feel more manageable. \n\nMomentum often grows from repeated experiences of achievement.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (43, 'Your Brain Hates Ambiguity', 'Unclear goals create uncertainty and hesitation. Defining exactly what success looks like makes action easier and more consistent.', 'https://doi.org/10.1037/0033-2909.106.2.265'),
    (44, 'Dopamine Drives Pursuit', 'Dopamine is closely linked to desire and motivation. It encourages exploration and goal-seeking rather than simply producing pleasure.', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3032992/'),
    (45, 'Habits Can Outlive Motivation', 'Motivation comes and goes, but habits can continue with little conscious effort. This is why systems often outperform willpower.', 'https://doi.org/10.1002/ejsp.674'),
    (46, 'Willpower Is Not Infinite', 'Self-control can become harder after long periods of effort or stress. \n\nManaging energy is often more effective than relying solely on discipline.', 'https://www.apa.org/topics/personality/willpower'),
    (47, 'Visual Cues Influence Choices', 'What is visible tends to be chosen more often. Small changes in what you see every day can dramatically influence behavior.', 'https://behavioraleconomics.com/resources/mini-encyclopedia-of-be/salience/'),
    (48, 'Rewards Strengthen Learning', 'Behaviors followed by satisfying outcomes become more likely to occur again. \n\nReward is one of the brain''s most powerful learning mechanisms.', 'https://www.simplypsychology.org/operant-conditioning.html'),
    (49, 'Attention Narrows Under Stress', 'Stress directs attention toward immediate threats and concerns. While useful for survival, it can make creative thinking more difficult.', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2907136/'),
    (50, 'The Brain Seeks Efficiency', 'Repeated behaviors gradually become automatic because automation saves energy. \n\nHabits are the brain''s way of reducing cognitive workload.', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4826769/'),
    (51, 'Curiosity Enhances Memory', 'When you''re genuinely curious about something, your brain becomes more receptive to learning. \n\nInformation acquired during states of curiosity is often remembered for longer.', 'https://www.cell.com/neuron/fulltext/S0896-6273(14)00062-5'),
    (52, 'Friction Shapes Behavior', 'Tiny obstacles can dramatically reduce the likelihood of an action. \n\nLikewise, making a behavior easier can significantly increase the chances of doing it.', 'https://www.behavioraleconomics.com/resources/mini-encyclopedia-of-be/nudge/'),
    (53, 'The Mere Exposure Effect', 'The more often you encounter something, the more familiar and appealing it tends to become. \n\nRepetition influences preferences more than most people realize.', 'https://en.wikipedia.org/wiki/Mere-exposure_effect'),
    (54, 'Energy Affects Discipline', 'Many failures of self-control are actually failures of energy management. \n\nSleep, nutrition and recovery often matter more than motivation.', 'https://www.sleepfoundation.org/sleep-deprivation'),
    (55, 'Rewards Lose Power Over Time', 'The brain quickly adapts to repeated rewards. What once felt exciting can become normal, encouraging people to seek novelty or greater challenges.', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3179598/'),
    (56, 'Focus Requires Exclusion', 'Concentrating deeply means actively ignoring countless other possibilities. \n\nEvery act of attention is also an act of deliberate omission.', 'https://www.simonsfoundation.org/2015/05/14/the-invisible-gorilla-experiment/'),
    (57, 'Momentum Is Real', 'Completing one productive task increases the likelihood of starting another. \n\nProgress tends to create more progress through positive reinforcement.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (58, 'Habits Thrive on Stability', 'Stable environments make routines easier to maintain. Frequent changes force the brain to make more decisions and consume more energy.', 'https://doi.org/10.1002/ejsp.674'),
    (59, 'Novelty Activates Attention', 'New experiences naturally attract cognitive resources. The brain is wired to notice unfamiliar situations because they may contain opportunities or threats.', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3181993/'),
    (60, 'Tiny Delays Reduce Impulses', 'Even a brief pause before acting can improve decision-making. \n\nA few seconds of reflection are often enough to reduce impulsive behavior.', 'https://www.apa.org/monitor/2013/03/mind-time'),
    (61, 'Every Habit Casts a Vote', 'Each action is a small vote for the type of person you want to become. \n\nIdentity is shaped gradually through repeated behaviors rather than single decisions.', 'https://jamesclear.com/identity-based-habits'),
    (62, 'Discipline Is Environmental Magic', 'The easiest temptation to resist is the one that never appears. \n\nDesigning your environment can often outperform relying on self-control alone.', 'https://doi.org/10.1177/0146167210390247'),
    (63, 'Attention Is Your Most Valuable Currency', 'Time is limited, but attention is even more precious. The quality of your life is strongly influenced by where you direct your focus each day.', 'https://www.simonsfoundation.org/2015/05/14/the-invisible-gorilla-experiment/'),
    (64, 'Motivation Visits, Systems Stay', 'Motivation can be unpredictable, but systems continue working even when enthusiasm fades. \n\nConsistent processes create reliable results.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (65, 'A Distracted Mind Travels in Circles', 'Effort without focus often produces movement without progress. \n\nConcentration helps transform energy into meaningful results.', 'https://www.apa.org/topics/personality/willpower'),
    (66, 'Every Cue Opens a Door', 'Small triggers can launch powerful chains of behavior. Many habits begin with a simple signal that tells the brain it''s time to act.', 'https://cancercontrol.cancer.gov/brp/research/constructs/implementation-intentions'),
    (67, 'Growth Hides Beyond Comfort', 'Improvement rarely happens inside familiar territory. \n\nModerate challenges encourage adaptation, learning and skill development.', 'https://www.theguardian.com/wellness/2025/may/08/what-is-flow-psychology'),
    (68, 'Consistency Beats Intensity', 'Extraordinary results often come from ordinary actions repeated over long periods. \n\nSustainable habits usually outperform occasional bursts of effort.', 'https://doi.org/10.1002/ejsp.674'),
    (69, 'Your Future Self Is Watching', 'The decisions you make today shape the opportunities available tomorrow. \n\nSmall choices accumulate into long-term consequences.', 'https://www.apa.org/monitor/2013/03/mind-time'),
    (70, 'Focus Is a Superpower', 'In an age of constant distractions, the ability to sustain attention has become increasingly rare and valuable.', 'https://www.simonsfoundation.org/2015/05/14/the-invisible-gorilla-experiment/'),
    (71, 'The Two-Minute Rule', 'Large habits often begin with very small actions. \n\nIf a behavior takes less than two minutes to start, you''re far more likely to do it consistently.', 'https://jamesclear.com/how-to-stop-procrastinating'),
    (72, 'Action Creates Clarity', 'People often wait for certainty before acting, but action itself generates information. \n\nProgress frequently reveals the next step.', 'https://doi.org/10.1037/0003-066X.54.7.493'),
    (73, 'Memory Loves Retrieval', 'Actively recalling information strengthens memory more effectively than simply reviewing it. \n\nRetrieval acts like exercise for the brain.', 'https://www.apa.org/science/about/psa/2016/06/learning-memory'),
    (74, 'The Testing Effect', 'Testing yourself is one of the most effective learning strategies available. The effort of retrieval helps create stronger memories.', 'https://www.apa.org/science/about/psa/2016/06/learning-memory'),
    (75, 'Choice Can Be Exhausting', 'More options do not always lead to better outcomes. Excessive choice can increase stress, delay decisions, and reduce satisfaction.', 'https://en.wikipedia.org/wiki/The_Paradox_of_Choice'),
    (76, 'Habits Need Repetition, Not Perfection', 'Long-term consistency matters more than flawless execution. \n\nMissing one day rarely matters; abandoning the habit entirely does.', 'https://jamesclear.com/habit-guide'),
    (77, 'Emotions Drive Attention', 'Emotional experiences naturally capture awareness and remain memorable. \n\nBrain prioritizes information that feels personally significant.', 'https://www.ncbi.nlm.nih.gov/books/NBK92765/'),
    (78, 'The Brain Seeks Patterns', 'Humans are natural pattern-detection machines. Finding structure helps us understand the world and make predictions about the future.', 'https://www.britannica.com/science/pattern-recognition'),
    (79, 'Deadlines Change Behavior', 'Constraints create urgency and encourage prioritization. Without deadlines, many tasks expand indefinitely and lose momentum.', 'https://hbr.org/2015/12/research-we-do-our-best-work-under-pressure'),
    (80, 'The First Step Changes Everything', 'Beginning a task often reduces anxiety and uncertainty. \n\nOnce started, the brain tends to perceive the challenge as more manageable.', 'https://behavioralscientist.org/how-to-build-habits-by-starting-small/'),
    (81, 'Context Triggers Memory', 'Memories are often linked to the environment in which they were formed. \n\nReturning to a familiar place can help you recall information that seemed forgotten.', 'https://www.simplypsychology.org/context-dependent-memory.html'),
    (82, 'Your Brain Rewards Progress', 'The brain is highly sensitive to signs of advancement. \n\nEven small improvements can generate positive emotions that reinforce continued effort.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (83, 'Attention Has a Spotlight', 'Focusing intensely on one thing can make other information nearly invisible. \n\nWhat you notice is often determined by what you''re already looking for.', 'https://www.simonsfoundation.org/2015/05/14/the-invisible-gorilla-experiment/'),
    (84, 'Practice Makes Neural Pathways Stronger', 'Every repetition strengthens the neural circuits involved in a skill. \n\nConsistent practice gradually makes actions faster, easier, and more automatic.', 'https://www.ncbi.nlm.nih.gov/books/NBK10921/'),
    (85, 'Novel Environments Spark Creativity', 'New places expose the brain to unfamiliar stimuli and perspectives. This can encourage flexible thinking and generate fresh ideas.', 'https://www.scientificamerican.com/article/why-walking-helps-us-think/'),
    (86, 'People Overestimate Future Motivation', 'Many people assume their future selves will have more discipline and energy. \n\nPlanning around today''s reality is often more effective than hoping for tomorrow''s motivation.', 'https://www.apa.org/monitor/2013/03/mind-time'),
    (87, 'Success Leaves Clues', 'Studying what already works can be just as valuable as identifying mistakes. \n\nSuccessful patterns often reveal practical strategies worth repeating.', 'https://positivepsychology.com/solution-focused-therapy/'),
    (88, 'Frustration Is Part of Learning', 'Struggling with a difficult concept can feel uncomfortable, but that effort often strengthens understanding and retention over time.', 'https://www.apa.org/science/about/psa/2016/06/learning-memory'),
    (89, 'Attention Is Drawn to Contrast', 'Differences in color, size, movement, or sound naturally attract attention. \n\nOur brains evolved to quickly notice things that stand out.', 'https://behavioraleconomics.com/resources/mini-encyclopedia-of-be/salience/'),
    (90, 'Consistency Creates Trust', 'Repeated actions build confidence in your abilities. Keeping small promises to yourself strengthens self-belief and reliability.', 'https://jamesclear.com/identity-based-habits'),
    (91, 'The Brain Prefers Immediate Rewards', 'Immediate rewards often feel more compelling than larger future benefits. This tendency helps explain procrastination and impulsive choices.', 'https://en.wikipedia.org/wiki/Delay_discounting'),
    (92, 'Visible Progress Motivates', 'Tracking streaks, milestones, or completed tasks provides evidence of growth. \n\nVisible progress makes long-term goals feel more achievable.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (93, 'Curiosity Is a Cognitive Magnet', 'Unanswered questions naturally pull attention toward their solutions. \n\nCuriosity transforms learning from a chore into an engaging pursuit.', 'https://www.cell.com/neuron/fulltext/S0896-6273(14)00062-5'),
    (94, 'Learning Benefits From Spacing', 'Information is retained more effectively when learning is spread across multiple sessions. \n\nSpaced repetition consistently outperforms cramming.', 'https://www.apa.org/science/about/psa/2016/06/learning-memory'),
    (95, 'Rituals Reduce Mental Load', 'Simple routines reduce uncertainty and conserve mental energy. \n\nRituals can help people perform consistently under pressure.', 'https://hbr.org/2012/04/why-successful-people-have-ri'),
    (96, 'Your Mood Shapes Attention', 'Emotional states influence what information receives priority.\n\nPeople often notice different opportunities and threats depending on how they feel.', 'https://www.ncbi.nlm.nih.gov/books/NBK92765/'),
    (97, 'Progress Is Easier to Maintain Than Start', 'Creating momentum requires effort, but maintaining it is often simpler. \n\nOnce a habit becomes established, continuation feels more natural.', 'https://hbr.org/2011/05/the-power-of-small-wins'),
    (98, 'Tiny Improvements Compound', 'Small gains repeated consistently can produce remarkable long-term results. \n\nImprovement often arrives gradually before becoming obvious.', 'https://jamesclear.com/marginal-gains'),
    (99, 'The Brain Learns During Rest', 'Learning doesn''t stop when practice ends. During rest, the brain continues processing and organizing information behind the scenes.', 'https://www.nih.gov/news-events/nih-research-matters/resting-brain-may-replay-compress-memories'),
    (100, 'Sleep Strengthens Memory', 'Sleep plays a critical role in consolidating memories. \n\nImportant information is often reinforced and organized while you rest.', 'https://www.sleepfoundation.org/how-sleep-works/memory-and-sleep'),
    (101, 'Goals Direct Attention', 'Clear goals help the brain determine what matters and what can be ignored. \n\nWithout direction, attention is more vulnerable to distractions.', 'https://doi.org/10.1037/0033-2909.106.2.265'),
    (102, 'Rewards Shape Habits', 'Behaviors followed by positive outcomes become more likely to repeat. \n\nReward strengthens the connection between action and future behavior.', 'https://www.simplypsychology.org/operant-conditioning.html'),
    (103, 'Identity Influences Behavior', 'People naturally act in ways that align with their self-image. \n\nChanging how you see yourself can influence what you consistently do.', 'https://jamesclear.com/identity-based-habits'),
    (104, 'Breaks Improve Performance', 'Sustained concentration benefits from occasional recovery periods. \n\nWell-timed breaks help preserve focus and reduce mental fatigue.', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5551286/'),
    (105, 'Effort Increases Value', 'People often value outcomes more when they have invested effort to achieve them. \n\nHard-earned rewards tend to feel more meaningful.', 'https://en.wikipedia.org/wiki/IKEA_effect'),
    (106, 'Social Norms Are Powerful', 'Human behavior is strongly influenced by the actions of others. \n\nWe often adjust our choices to match what seems normal within a group.', 'https://www.behaviouralinsights.co.uk/social-norms/'),
    (107, 'Attention Can Become a Habit', 'What you repeatedly focus on shapes what you notice in the future. \n\nAttention patterns can become automatic over time.', 'https://www.ncbi.nlm.nih.gov/books/NBK11509/'),
    (108, 'Uncertainty Fuels Curiosity', 'Gaps in knowledge create a natural desire to learn more. \n\nThe brain often finds unanswered questions difficult to ignore.', 'https://www.science.org/doi/10.1126/science.aaa6142'),
    (109, 'Reflection Improves Growth', 'Taking time to review experiences helps transform them into lessons. \n\nReflection turns activity into learning and learning into wisdom.', 'https://hbr.org/2014/05/why-you-should-make-time-for-self-reflection-even-if-you-hate-doing-it'),
    (110, 'Mastery Requires Deliberate Practice', 'Experts improve by targeting specific weaknesses rather than repeating what they already know. \n\nFocused practice accelerates skill development.', 'https://doi.org/10.1037/0033-295X.100.3.363');